This linked-list queue has a bug in `dequeue`. What happens when you run `q.enqueue(1)`, `q.dequeue()`, `q.enqueue(2)`, `q.dequeue()`?

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedQueue:
    def __init__(self):
        self.head = None
        self.tail = None

    def enqueue(self, value):
        node = Node(value)
        if self.tail is None:      # queue is empty
            self.head = node
        else:
            self.tail.next = node
        self.tail = node

    def dequeue(self):
        node = self.head
        self.head = node.next
        return node.value
```
